export default function Citation() {
    return (
        <div className="content-doc text-left">
            <h2 className="text-[#000000] font-bold mt-5 mb-3 w-full pl-8 pr-8">Cite RNAproDB</h2>

            <div className="pl-8 pr-8 pb-8 mb-12 w-full">
                <p className="mx-auto text-left text-lg">
                    If you use RNAproDB in your work, please cite:
                </p>
                <p className="mx-auto text-left mb-8">
                RNAproDB: a webserver and interactive database for analyzing protein–RNA interactions; Raktim Mitra, Ari S. Cohen, Wei Yu Tang, Hirad Hosseini, Yongchan Hong, Helen M. Berman, Remo Rohs; Journal of Molecular Biology. <a href="https://doi.org/10.1016/j.jmb.2025.169012" target="_blank" rel="noreferrer">doi.org/10.1016/j.jmb.2025.169012</a>
                </p>
            </div>
        </div>
    );
}
